def _build_lifecycle_snapshot(
    *,
    session: Session,
    pulse: LegacySession,
    event_type: WebhookEventType,
    status: str,
    occurred_at: datetime,
    allow_pending_owner: bool = False,
) -> dict[str, Any]:
    """Snapshot trusted ownership and the same canonical name displayed by Pulse."""
    payload: dict[str, Any] = {
        "eventType": event_type.value,
        "projectId": pulse.growthos_project_id,
        "pulseId": str(pulse.id),
        "status": status,
        "timestamp": ensure_aware_utc(occurred_at)
        .isoformat(timespec="milliseconds")
        .replace("+00:00", "Z"),
        "environment": settings.ENVIRONMENT or "unknown",
        "resumeUrl": _resume_url(pulse),
        "userId": _owner_email(session, pulse, allow_pending=allow_pending_owner),
        "name": _canonical_name(session, pulse),
    }
    if payload["userId"] is None:
        payload[PENDING_OWNER_SUB_KEY] = pulse.owner_sub

    if event_type == WebhookEventType.PULSE_FINDINGS_COMPLETED:
        findings_share_url = _share_url(session, pulse)
        payload.update(
            {
                "findingsShareUrl": findings_share_url,
                "pulseLink": findings_share_url or payload["resumeUrl"],
                "cost": 3 if pulse.session_type == LegacySessionType.COMPARE.value else 1,
                "reportType": "compare"
                if pulse.session_type == LegacySessionType.COMPARE.value
                else "pulse",
            }
        )
    elif event_type == WebhookEventType.PULSE_FINDINGS_FAILED:
        payload["error"] = {
            "code": pulse.error_code or "task_failed",
            "message": "Pulse findings generation failed.",
        }
    payload["correlationId"] = pulse.growthos_correlation_id
    return payload


def _owner_email(
    session: Session, pulse: LegacySession, *, allow_pending: bool = False
) -> str | None:
    owner = session.get(Auth0UserDirectory, pulse.owner_sub) if pulse.owner_sub else None
    if owner is None and pulse.owner_sub and allow_pending:
        # The owner exists in Auth0 but was never mirrored locally. The product
        # transaction must not call Auth0; the delivery worker syncs it first.
        return None
    return required_text(directory_owner_email(owner), "userId")


def directory_owner_email(owner: Auth0UserDirectory | None) -> str | None:
    """Resolve the same owner email Customer API sends, even without a root profile email.

    Enterprise SAML connections without an email attribute mapping (Accenture)
    leave the Auth0 root ``email`` empty but still assert the address as an
    emailAddress NameID, which the post-login Action also records.
    """
    if owner is None:
        return None
    raw = getattr(owner, "raw_payload", None)
    raw = raw if isinstance(raw, dict) else {}
    name_id = raw.get("nameIdAttributes")
    metadata = raw.get("user_metadata")
    candidates = (
        owner.email,
        name_id.get("value")
        if isinstance(name_id, dict) and name_id.get("Format") == _SAML_EMAIL_NAME_ID_FORMAT
        else None,
        metadata.get("resolved_email") if isinstance(metadata, dict) else None,
    )
    for candidate in candidates:
        if isinstance(candidate, str) and _OWNER_EMAIL_PATTERN.fullmatch(candidate.strip()):
            return candidate.strip()
    return None


