    from app.services.legacy.service import LegacySessionService  # noqa: PLC0415

    # This resolver also supplies the persisted asset/Compare default shown in UI.
    name = (
        LegacySessionService._session_display_name_from_primary_asset(
            pulse, primary_asset=None, db_session=session
        )
        if pulse.display_name_override
        or (pulse.experience_name and pulse.session_type != LegacySessionType.COMPARE.value)
        else LegacySessionService._session_display_name(pulse, session)
    )
    name = required_text(name, "name")
    if pulse.display_name_override:
        pulse.display_name_override = name
    elif not pulse.experience_name:
