async function scheduleGrowthOSLifecycleAfterCommit(
  transaction,
  session,
  eventType,
  status,
  idempotencyKey,
  error = null
) {
  const projectId = session?.growthosProjectId ?? session?.correlationId;
  // Native owns lifecycle delivery for its persisted customer-api computation delegate.
  if (!session?.id || session.proxyLaunchId || !projectId?.trim()) return;
  const mode = resolveGrowthOSWebhookMode();
  if (!mode.terminalFailedAt && mode.payloadMode === 'legacy') return;
  const eventContext = {
    automatedInsightSessionId: session.id,
    projectId,
    correlationId: session.growthosCorrelationId ?? null,
    eventType,
    status,
    idempotencyKey,
    error,
    ...(eventType === 'pulse.findings_generation_started'
      ? { taskId: idempotencyKey, syncToLegacyPulse: Boolean(session.features?.pulseProxy) }
      : {}),
  };
  const captured = mode.terminalFailedAt
    ? mode
    : await captureGrowthOSPayload(() => buildGrowthOSPulseLifecyclePayload(eventContext, { transaction }));
  return registerGrowthOSWebhookEvent(
    transaction,
    {
      logicalEventId: `growthos:pulse_lifecycle:${eventType}:${session.id}${idempotencyKey ? `:${idempotencyKey}` : ''}`,
      automatedInsightSessionId: session.id,
      eventType,
      eventContext,
      payloadMode: mode.payloadMode,
      ...captured,
    },
    enqueueGrowthOSOutboxEvent
  );
}

async function recordGrowthOSFindingsFailure({ automatedInsightSessionId, taskId }) {
  if (!automatedInsightSessionId || !taskId) return;
  return sequelize.transaction(async (transaction) => {
    const task = await models.AutomatedInsightSessionTask.findOne({
      where: { automatedInsightSessionId, taskId },
      transaction,
      lock: transaction.LOCK.UPDATE,
    });
    if (!task || task.completedAt || task.failedAt) return;
    const session = await models.AutomatedInsightSession.findByPk(automatedInsightSessionId, { transaction });
    if (!session) return;
    await task.update({ failedAt: new Date() }, { transaction });
    await scheduleGrowthOSLifecycleAfterCommit(
      transaction,
      session,
      'pulse.findings_failed',
      'failed',
      taskId,
      {
        code: 'task_failed',
        message: 'Pulse findings generation failed.',
      }
    );
  });
}

