function getOutermostTransaction(transaction) {
  let currentTransaction = transaction;

  while (currentTransaction?.parent) {
    currentTransaction = currentTransaction.parent;
  }

  return currentTransaction ?? null;
}

function runAfterCommit(transaction, fn) {
  const commitTransaction = getOutermostTransaction(transaction);

  if (typeof commitTransaction?.afterCommit === 'function') {
    commitTransaction.afterCommit(fn);
    return;
  }

  fn();
}

